/**
 * Claude Code hook matcher semantics, shared by the tool dispatchers so they
 * route exactly as CC reads the shipped hooks.json matchers: absent, "" or
 * "*" matches every tool; word characters, "-" and "|" are an exact list;
 * anything else is an unanchored regular expression (so "mcp__context7__*"
 * is a regex to CC, not a prefix).
 */
export function ccMatcherMatches(matcher: string | undefined, tool: string): boolean {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  if (/^[\w|-]+$/.test(matcher)) return matcher.split('|').includes(tool);
  try {
    return new RegExp(matcher).test(tool);
  } catch {
    return false;
  }
}
